import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        if opp_last == 'D':
            return 'D'
        return 'C'

    opp_defects = 0
    opp_coops = 0
    my_defects = 0
    for me, them in history:
        if them == 'D':
            opp_defects += 1
        else:
            opp_coops += 1
        if me == 'D':
            my_defects += 1

    rate = opp_defects / n

    # Count consecutive defections by opponent at the end
    tail_def = 0
    for me, them in reversed(history):
        if them == 'D':
            tail_def += 1
        else:
            break

    # Count consecutive mutual cooperation at the end
    tail_cc = 0
    for me, them in reversed(history):
        if me == 'C' and them == 'C':
            tail_cc += 1
        else:
            break

    # If opponent just defected, retaliate but consider forgiveness
    if opp_last == 'D':
        if tail_def >= 3:
            return 'D'
        if rate > 0.35:
            return 'D'
        # occasional forgiveness to rebuild cooperation
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if rate > 0.5:
        # very untrustworthy opponent: exploit
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    if rate > 0.25:
        # moderately defective: mostly cooperate, occasional opportunistic defect
        if tail_cc >= 2 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Opponent mostly cooperates. Try an occasional probe if we haven't recently.
    if n >= 4 and tail_cc >= 3 and rng.random() < 0.07:
        return 'D'

    # Late game: if leading strategy ending, consider exploitation last rounds
    remaining = 100 - n
    if remaining <= 2 and rate < 0.2:
        if remaining == 1:
            return 'D'
        if rng.random() < 0.5:
            return 'D'

    return 'C'
